NS_IMETHODIMP FolderInfo::OrFlags(int32_t aFlags, int32_t* aOutFlags) {
  NS_ENSURE_ARG_POINTER(aOutFlags);
  uint32_t flags = MOZ_TRY(FolderDB().GetFolderFlags(mFolderId));
  flags |= aFlags;
  MOZ_TRY(FolderDB().UpdateFlags(mFolderId, flags));
  *aOutFlags = flags;
  return NS_OK;
}

